// Cloudflare Pages Function backing the species-review tool's live state
// (review/public/index.html, generated by scripts/build_photo_review.py).
// Bound to the REVIEW_STATE KV namespace via review/wrangler.toml.
//
//   GET  /api/review-state   -> current state as JSON ("{}" if never written)
//   POST /api/review-state   -> overwrite the state with the request body
//                                (last-write-wins -- the page always POSTs
//                                its full current state, not a delta)
//
// TOKEN is not real security -- it ships in the page's own client-side JS,
// so anyone who views the page source can read it. It only keeps this
// public, unauthenticated endpoint from being hit by crawlers/scanners that
// stumble on the URL, which is proportionate to the actual stakes here
// (recoverable species-review data, not sensitive information). Keep this
// value in sync with TOKEN in scripts/build_photo_review.py.
const TOKEN = "5d1ebe80f5e64c4d61380df93c29c74d";
const KEY = "state";
const MAX_BODY_BYTES = 500_000; // generous for ~50 species of review state

export async function onRequestGet({ env }) {
  const value = await env.REVIEW_STATE.get(KEY);
  return new Response(value ?? "{}", {
    headers: { "content-type": "application/json", "cache-control": "no-store" },
  });
}

export async function onRequestPost({ request, env }) {
  if (request.headers.get("x-review-token") !== TOKEN) {
    return new Response("forbidden", { status: 403 });
  }
  const body = await request.text();
  if (body.length > MAX_BODY_BYTES) {
    return new Response("too large", { status: 413 });
  }
  try {
    JSON.parse(body); // reject non-JSON before it ever reaches KV
  } catch {
    return new Response("invalid json", { status: 400 });
  }
  await env.REVIEW_STATE.put(KEY, body);
  return new Response("ok");
}
